import { createContext, useContext, useState, type ReactNode } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { asString, useSearchParam } from '../../url/useSearchParam';
import { claimsKey } from './useClaims';

type Selection = { selected: Set<string>; toggle: (id: string, on: boolean) => void; clear: () => void };

const SelectionContext = createContext<Selection | null>(null);

/** The claims ticked with their select checkbox, shared by every claim row and the bulk buttons. */
export function ClaimSelection({ children }: { children: ReactNode }) {
  const [selected, setSelected] = useState<Set<string>>(() => new Set());
  const toggle = (id: string, on: boolean) =>
    setSelected((was) => {
      const next = new Set(was);
      if (on) next.add(id);
      else next.delete(id);
      return next;
    });
  const clear = () => setSelected(new Set());
  return <SelectionContext.Provider value={{ selected, toggle, clear }}>{children}</SelectionContext.Provider>;
}

export function useClaimSelection(): Selection {
  const selection = useContext(SelectionContext);
  if (!selection) throw new Error('useClaimSelection outside ClaimSelection');
  return selection;
}

/** A claim row's select checkbox. */
export function ClaimSelect({ claimId }: { claimId: string }) {
  const { selected, toggle } = useClaimSelection();
  return (
    <input
      type="checkbox"
      data-testid="claim-select"
      checked={selected.has(claimId)}
      onChange={(e) => toggle(claimId, e.target.checked)}
    />
  );
}

// Opens the selected claims together: the server opens and numbers each that can be opened, in list
// order (people in the order they were added, newest claim first within a person), and leaves each
// that cannot as it is. Then shows how many were opened and how many were refused, and clears the
// selection; pressing again removes the old counts until the new ones are in.
export function BulkOpenButton() {
  const [sheet] = useSearchParam('sheet', asString);
  const [user] = useSearchParam('user', asString);
  const queryClient = useQueryClient();
  const once = useSubmitOnce();
  const { selected, clear } = useClaimSelection();

  const open = useMutation({
    mutationFn: (claimIds: string[]) =>
      postJson<{ opened: number; refused: number }>(
        `/api/sheets/${encodeURIComponent(sheet)}/claims/bulk-open`,
        { claimIds, user },
      ),
    onSuccess: () => {
      clear();
      return queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
    },
  });

  return (
    <p>
      <button
        type="button"
        data-testid="bulk-open"
        onClick={() => {
          open.reset();
          const ids = [...selected];
          once(() => open.mutateAsync(ids));
        }}
      >
        Open selected
      </button>
      {open.isSuccess && (
        <>
          {' '}
          Opened <span data-testid="bulk-opened">{open.data.opened}</span>, refused{' '}
          <span data-testid="bulk-refused">{open.data.refused}</span>
        </>
      )}
      {open.isError && (
        <span data-testid="bulk-open-error" role="alert">
          {' '}
          The selected claims could not be opened.
        </span>
      )}
    </p>
  );
}

// Settles the selected claims together: the server settles each by the rules of settling one claim, in
// list order, by the signed-in user; a claim sent to PENDING counts as settled, one that cannot be
// settled is left as it is. Then shows how many were settled and how many were refused, and clears
// the selection; pressing again removes the old counts until the new ones are in.
export function BulkSettleButton() {
  const [sheet] = useSearchParam('sheet', asString);
  const [user] = useSearchParam('user', asString);
  const queryClient = useQueryClient();
  const once = useSubmitOnce();
  const { selected, clear } = useClaimSelection();

  const settle = useMutation({
    mutationFn: (claimIds: string[]) =>
      postJson<{ settled: number; refused: number }>(
        `/api/sheets/${encodeURIComponent(sheet)}/claims/bulk-settle`,
        { claimIds, user },
      ),
    onSuccess: () => {
      clear();
      return queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
    },
  });

  return (
    <p>
      <button
        type="button"
        data-testid="bulk-settle"
        onClick={() => {
          settle.reset();
          const ids = [...selected];
          once(() => settle.mutateAsync(ids));
        }}
      >
        Settle selected
      </button>
      {settle.isSuccess && (
        <>
          {' '}
          Settled <span data-testid="bulk-settled">{settle.data.settled}</span>, refused{' '}
          <span data-testid="bulk-settle-refused">{settle.data.refused}</span>
        </>
      )}
      {settle.isError && (
        <span data-testid="bulk-settle-error" role="alert">
          {' '}
          The selected claims could not be settled.
        </span>
      )}
    </p>
  );
}
import { asString, useSearchParam } from '../../url/useSearchParam';
import { ClaimForm } from '../claims/ClaimForm';
import { BulkOpenButton, BulkSettleButton, ClaimSelection } from '../claims/BulkOpen';
import { ClaimList } from '../claims/ClaimList';
import { sumAmounts } from '../claims/useClaims';
import { formatCents, showDue } from '../rates/due';
import { rateOn } from '../rates/useRates';
import { StatementButton } from '../statements/StatementButton';
import { UnstateButton } from '../statements/UnstateButton';
import { SummaryPanel } from '../summary/SummaryPanel';
import { HoldControl } from './HoldControl';
import { PasteClaims } from './PasteClaims';
import { PatronControl } from './PatronControl';
import { QuickAdd } from './QuickAdd';
import { RetireControl } from './RetireControl';
import { WatchControl } from './WatchControl';
import { useWatches } from './useWatches';
import { downloadCsv } from './csv';
import { ShowRetired, useShowRetired } from './ShowRetired';
import { gradeOn } from './usePeople';
import { usePersonPeriodDueTotal } from '../periods/usePeriodDueTotal';
import { usePeriods } from '../periods/usePeriods';
import { useSheetFigures } from './useSheetFigures';

// Every person on the sheet in the order they were added, with their name, grade (the one in force on the sheet's today), claimed (the
// sum of their OPEN and SETTLED claims), due-total (the
// sum of their counting claims' already-rounded dues, at most the sheet's cap — their excess shows how far the sum is above it, else 0.00; n/a when their grade has no rate today and no settled or stated claim keeps a figure),
// their due-total for each period (fixed when the period was closed, 0.00 for a person added after),
// whether they are retired and from when, whether they have any hold, and their holds (a person's OPEN claims dated within a hold, unless bound by a
// statement, count in neither their figures nor the sheet's totals; their other claims still do), their overdue count and
// patrons (names, sorted) and backing (their patrons' settled figures added up: each patron's SETTLED claims dated within the 90 days up to and including today, at their frozen figures; 0.00 with none),
// their overdue count and overdue-total (how many of their counting claims are overdue, and the sum of those claims' dues with their late charges, n/a adding nothing), their statements (the statement button, how many were taken, the last one's due-total and date) and their claims; then the
// sheet's claimed-total, due-total (the people's due-totals added up, skipping n/a), overdue count and overdue-total (the
// due-total and overdue-total leave out the single highest and lowest person's figure when three or more have one). Retired
// people have no row unless "show retired" is on, and from their retirement date their OPEN and PENDING claims, unless bound by a statement, leave every live total.
// Then the summary panel, worked from these same figures. The export button downloads every person (retired too), in list
// order, as CSV: name, grade in force today, retired-from (or nothing) and due-total as shown. Claims ticked
// with their select checkbox are opened together with the bulk open button.
export function PeopleList() {
  const [sheet] = useSearchParam('sheet', asString);
  const [user] = useSearchParam('user', asString);
  const [, setEditing] = useSearchParam('editPerson', asString);
  const watched = useWatches(sheet, user);
  const { people, claims, rates, today, byId, live, totalOf, excessOf, overdue, overdueTotal, sheetDueTotal, sheetOverdueTotal, statusCount, isActive, recentSettledOf } = useSheetFigures(sheet);
  const [showRetired] = useShowRetired();
  const periods = usePeriods(sheet);
  const periodDueOf = usePersonPeriodDueTotal(sheet);
  const listed = showRetired ? people : people.filter((p) => !p.retired);
  const backing = (p: (typeof people)[number]) =>
    formatCents(p.patronIds.reduce((sum, id) => {
      const patron = byId.get(id);
      return patron ? sum + recentSettledOf(patron) : sum;
    }, 0n));

  const overdueOf = (personId: string) => overdue.filter((c) => c.personId === personId);
  return (
    <ClaimSelection>
      <QuickAdd />
      <PasteClaims />
      <ShowRetired />
      <button
        type="button"
        data-testid="export-people"
        onClick={() =>
          downloadCsv(
            'people.csv',
            [['name', 'grade', 'retired-from', 'due-total'], ...people.map((p) => [p.name, gradeOn(p, today), p.retiredFrom, showDue(totalOf(p))])],
          )
        }
      >
        Export CSV
      </button>
      <BulkOpenButton />
      <BulkSettleButton />
      <table data-testid="people">
        <thead>
          <tr>
            <th>Name</th>
            <th>Grade</th>
            <th>Terms</th>
            <th>Claimed</th>
            <th>Due</th>
            <th>Excess</th>
            <th>Active</th>
            {periods.map((period) => (
              <th key={period.name}>Due {period.name}</th>
            ))}
            <th>Patrons</th>
            <th>Backing</th>
            <th>Overdue</th>
            <th>Overdue due</th>
            <th />
            <th>Watched</th>
            <th>Retired</th>
            <th>Retired from</th>
            <th>Hold</th>
            <th>Statements</th>
            <th>Last stated</th>
            <th>Stated on</th>
            <th>Claims</th>
          </tr>
        </thead>
        <tbody>
          {listed.map((p) => {
            const own = claims.filter((c) => c.personId === p.id);
            return (
              <tr key={p.id} data-testid={`person-row-${p.id}`}>
                <td data-testid="person-name">{p.name}</td>
                <td data-testid="person-grade">{gradeOn(p, today)}</td>
                <td data-testid="person-terms">{p.terms}</td>
                <td data-testid="person-claimed">{sumAmounts(live.filter((c) => c.personId === p.id))}</td>
                <td data-testid="person-due-total">{showDue(totalOf(p))}</td>
                <td data-testid="person-excess">{formatCents(excessOf(p))}</td>
                <td data-testid="person-active">{isActive(p) ? 'yes' : 'no'}</td>
                {periods.map((period) => (
                  <td key={period.name} data-testid={`person-period-${period.name}-due-total`}>
                    {formatCents(periodDueOf(period, p.id))}
                  </td>
                ))}
                <td data-testid="person-patrons">{p.patrons.join(', ')}</td>
                <td data-testid="person-backing">{backing(p)}</td>
                <td data-testid="person-overdue-count">{overdueOf(p.id).length}</td>
                <td data-testid="person-overdue-total">{overdueTotal(overdueOf(p.id))}</td>
                <td>
                  <button type="button" data-testid={`person-edit-${p.id}`} onClick={() => setEditing(p.id)}>
                    Edit
                  </button>{' '}
                  <StatementButton personId={p.id} />{' '}
                  <UnstateButton personId={p.id} />{' '}
                  <RetireControl personId={p.id} />{' '}
                  <HoldControl personId={p.id} holds={p.holds} />{' '}
                  <PatronControl personId={p.id} people={people} />{' '}
                  <WatchControl personId={p.id} watched={watched.includes(p.id)} />
                </td>
                <td data-testid="person-watched">{watched.includes(p.id) ? 'yes' : 'no'}</td>
                <td data-testid="person-retired">{p.retired ? 'yes' : 'no'}</td>
                <td data-testid="person-retired-from">{p.retiredFrom}</td>
                <td data-testid="person-hold">{p.held ? 'yes' : 'no'}</td>
                <td data-testid="person-statement-count">{p.statementCount}</td>
                <td data-testid="person-stated-total">{p.statedTotal}</td>
                <td data-testid="person-statement-date">{p.statementDate}</td>
                <td>
                  <ClaimList claims={own} people={people} rateOn={(date) => rateOn(rates, gradeOn(p, date), date)} />
                  <ClaimForm personId={p.id} claims={own} />
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
      <p>
        Claimed total: <span data-testid="rollup-claimed-total">{sumAmounts(live)}</span>
      </p>
      <p>
        Due total: <span data-testid="rollup-due-total">{sheetDueTotal}</span>
      </p>
      <p>
        Overdue: <span data-testid="rollup-overdue-count">{overdue.length}</span>
      </p>
      <p>
        Overdue total: <span data-testid="rollup-overdue-total">{sheetOverdueTotal}</span>
      </p>
      <SummaryPanel people={people} today={today} totalOf={totalOf} isActive={isActive} statusCount={statusCount} />
    </ClaimSelection>
  );
}
